public class StringSubstitutor_ESTest_test41 extends StringSubstitutor_ESTest_scaffolding {

    @Test(timeout = 4000)
    public void test41() throws Throwable {
        StringSubstitutor substitutor = new StringSubstitutor();

        StringBuilder buffer = new StringBuilder("}");
        char[] charsWithTrailingDollar = new char[5];
        charsWithTrailingDollar[4] = '$';

        StringBuilder afterCharArrayAppend = buffer.append(charsWithTrailingDollar);
        StringBuilder afterPrefixAppend = afterCharArrayAppend.append((CharSequence) "${");
        afterPrefixAppend.append("}");
        StringBuilder selfDuplicatedBuffer = afterPrefixAppend.append((Object) buffer);

        boolean changed = substitutor.replaceIn(selfDuplicatedBuffer);

        assertEquals("}\u0000\u0000\u0000\u0000${}}\u0000\u0000\u0000\u0000${}", selfDuplicatedBuffer.toString());
        assertTrue(changed);
    }
